        "overview": "This course covers the fundamental concepts of software engineering. Topics include software design concepts and principles, design of software quality, abstraction, refinement, modularity, software architecture, control hierarchy, structural partitioning, and data structure. Design methodology, data architecture, transformation mapping. Post processing design; optimization: interface design, foundations of human-computer interaction: Human centered development and evaluation. Procedural design: structure 112 programming, graphical notation, tabular notation, Program Design Language (PDL). Object-oriented design: concept of patterns and the use of APIs; modeling tools such as class diagrams, CRC cards, and UML use cases. Software: reuse and re-engineering. Client/server software development. Computer aided software development. An introduction to the concepts underlying the design of human-computer interaction: usability and affordances, systemic design methods, user conceptual models and interface metaphors, human cognitive and physical ergonomics, information and inter activity structures, design tool and environment. Structured around a set of case studies in which notable interface designs, and/or projects are analyzed as illustrative of underlying principles. Discussion of cases and interface analysis and design exercises. 113",
