        "overview": "Introduction to Computer Engineering (CPE 112) introduces students to various career paths, fundamental concepts, and the scope of Computer Engineering as a discipline. Topics include overview of computer hardware and software systems, digital logic fundamentals, basic programming concepts, number systems and Boolean algebra, introduction to computer networks, and professional ethics in computing. The course provides a solid foundation for subsequent studies in the Computer Engineering programme.",
