      "EEE324": {
        "code": "EEE 324",
        "title": "Linear systems",
        "semester": "Second Semester",
        "credits": 3,
        "contactHours": "Lecture - Two hours lectures per week",
        "location": "Hall B2-5",
        "lecturer": "Engr. Prof. M. O. Onibonoje, Mr. Victor Akinpelu",
        "textbooks": [
          "◼ Linear System by H. Bourles ◼ Control System by Norman Nise ◼ Feedback and Control Systems by Joseph J. DiStefano, Allen R. Stubberud and Ivan J. Williams"
        ],
        "overview": "Linear Systems provides students with a comprehensive foundation in the modeling, analysis, and evaluation of dynamic systems across electrical, mechanical, and thermal domains. The course begins by introducing mathematical models of physical systems and develops the concept of system analogies, enabling learners to translate problems from one physical domain to another. Emphasis is placed on control system classifications and feedback concepts, highlighting their 161 role in shaping system performance and ensuring desired outputs under varying conditions. Students explore transfer functions, block diagrams, and signal flow graphs, building the skills to represent, simplify, and interconnect systems efficiently. The course further investigates system responses, covering both transient and steady-state behaviors, and equips students with frequency-domain analysis tools such as root-locus, Bode plots, Nyquist diagrams, and polar plots for performance characterization and design insights. Stability analysis forms a crucial component, with techniques such as Routh-Hurwitz, Nyquist, and Bode criteria applied to determine robustness and reliability of systems. Finally, an introduction to analogue computer simulation enhances practical understanding by demonstrating system behavior and control strategies. By the end of the course, students will be able to model real-world systems, analyze responses, assess stability, and apply feedback principles, thereby gaining a strong analytical base for advanced courses in control engineering, signal processing, and system design. The knowledge gained equips learners to tackle contemporary industrial challenges where system modeling and control are vital, from automation and robotics to energy systems and communication networks.",
        "prerequisites": "Nil",
        "clos": [
          {
            "id": "CLO 1",
            "desc": "Develop mathematical models of 2,3,4 electrical, mechanical, and thermal systems using system analogies and differential equations.",
            "pos": "PO1, PO2"
          },
          {
            "id": "CLO 2",
            "desc": "Explain the classifications of control systems, and describe feedback concepts including their impact on system performance.",
            "pos": "PO2, PO3, PO4"
          },
          {
            "id": "CLO 3",
            "desc": "Analyze the transient and 1,2,5 3,4,6 1,2,5 frequency responses of linear systems using time-domain and frequency-domain methods Assess the stability of control 2,5,6 1,2,3 systems using techniques such as Routh-Hurwitz, Bode, and Nyquist criteria Construct and simplify transfer 1,3,4 functions, block diagrams, and 1,2,3 signal flow graphs to describe and",
            "pos": "PO1, PO2, PO5"
          },
          {
            "id": "CLO 4",
            "desc": "analyze control systems f)",
            "pos": "PO3, PO4, PO6"
          }
        ],
        "outlines": [
          "Week 1-3: Introduction and fundamental concepts.",
          "Week 4-6: Core operations and analytical frameworks.",
          "Week 7-9: Advanced modules and system architectures.",
          "Week 10-12: Practical design case studies and review.",
          "Week 13-15: Revision and comprehensive examinations."
        ],
        "lecturePlans": "Lectures hold on scheduled times per week in Hall B2-5. Mandatory practical and tutorial sessions commence in Week 3, mapping practical observations to theoretical calculations. Mid-semester tests are held in Week 8."
      },
