          "Week 4-6: Transfer functions and system modeling: electrical, mechanical, hydraulic,",
          "Week 7-9: pneumatic, thermal",
          "Week 10-12: Time response analysis and system classification",
          "Week 13-15: Stability analysis: Routh-Hurwitz criterion"
