      "EEE561": {
        "code": "EEE 561",
        "title": "Control Engineering",
        "semester": "First Semester",
        "credits": 3,
        "contactHours": "Lecture - Two hours lectures per week",
        "location": "Hall B-33",
        "lecturer": "Engr. Prof. M.O Onibonoje, Mr. Victor Akinpelu 166",
        "textbooks": [
          "· Linear State-Space Control Systems – Robert L. Williams · Modern Control Engineering – Katsuhiko Ogata"
        ],
        "overview": "Control Engineering provides students with an advanced understanding of modern control theory through the state-space approach, equipping them with both theoretical foundations and practical skills for the analysis and design of dynamic systems. The course begins with the formulation of state-space models and their relationship to transfer functions, enabling learners to bridge classical and modern control representations. Students will explore the role of eigenvalues and eigenvectors in determining system response and stability, while also mastering critical concepts such as controllability and observability that form the backbone of system design. Building on this foundation, the course emphasizes the design and implementation of state feedback controllers, observers, and compensators, with a strong focus on optimal control through the Linear Quadratic Regulator (LQR) framework. Real-world applications, including robotics, circuit synthesis, and signal processing, are integrated to illustrate the industrial relevance of control strategies. Additionally, students will gain hands-on experience with computer-aided tools for simulation, modeling, and optimization, preparing them for contemporary engineering challenges. By the end of the course, learners are expected to demonstrate the ability to analyze, design, and optimize control systems that meet performance criteria under practical constraints, while also appreciating the interdisciplinary applications of control engineering across electrical, mechanical, and electronic domains. This course thus fosters problem-solving, innovation, and lifelong learning, while strengthening students’ readiness to contribute effectively in research, industry, and advanced studies.",
        "prerequisites": "Nil",
        "clos": [
          {
            "id": "CLO 1",
            "desc": "Demonstrate proficiency in converting between transfer functions and state-space representations and recognize implications for system behavior. Analyse eigenvalues and 2,3,4 1,2 1,4,6 2,3 eigenvectors to assess system stability and response, applying concepts to real-world scenarios.",
            "pos": "PO2, PO4, PO6"
          },
          {
            "id": "CLO 2",
            "desc": "Design and implement state 3,5,6 2,3,5 feedback control systems and observers, including compensators and Linear Quadratic Regulators Optimize control strategies in 2,3,6 practical applications such as 3,4,6 robotics and signal processing using computer-aided tools. f)",
            "pos": "PO2, PO3, PO4"
          }
        ],
        "outlines": [
          "Week 1-3: Introduction and fundamental concepts.",
          "Week 4-6: Core operations and analytical frameworks.",
          "Week 7-9: Advanced modules and system architectures.",
          "Week 10-12: Practical design case studies and review.",
          "Week 13-15: Revision and comprehensive examinations."
        ],
        "lecturePlans": "Lectures hold on scheduled times per week in Hall B-33. Mandatory practical and tutorial sessions commence in Week 3, mapping practical observations to theoretical calculations. Mid-semester tests are held in Week 8."
      },
