      "EEE566": {
        "code": "EEE 566",
        "title": "Non-Linear systems",
        "semester": "Second Semester",
        "credits": 3,
        "contactHours": "Lecture - Two hours lectures per week",
        "location": "Hall B2-5",
        "lecturer": "Engr. Prof. M.O Onibonoje, Mr. Victor Akinpelu",
        "textbooks": [
          "Modern control theories: Non linear, optimal and Adaptive systems, Csak",
          "Applied Non linear control, Slotine, J.E (1991)",
          "Control Theory: Multivariable and Non linear Methods, Khali, H",
          "Non-linear Control systems, Marcel Dekker Inc, Vukic, Z, Kulija (2003)"
        ],
        "overview": "Non Linear Systems provides an advanced study of the principles, analysis, and applications of nonlinear control systems, which are fundamental to modern engineering practice. Unlike linear systems, nonlinear systems exhibit complex behaviors such as limit cycles, bifurcations, and instability, making their analysis critical in real-world scenarios where ideal assumptions of linearity no longer apply. The course introduces students to nonlinear differential equations, common sources of nonlinearities in engineering systems, and approximation techniques including linearization, piecewise linear methods, and describing functions for analyzing system stability and predicting limit cycles. Students will gain practical skills in evaluating system dynamics using phase-plane methods and Lyapunov’s stability theory, which are powerful tools for assessing nonlinear responses and ensuring robust control. In addition, the course bridges theory and practice by covering sampled-data systems with z-transform analysis and by incorporating programmable logic controllers (PLCs) for process automation applications, thus equipping learners with both analytical and industrially relevant competencies. Emphasis is placed on developing the ability to model, analyze, and design nonlinear control strategies for complex systems encountered in robotics, power systems, aerospace, and industrial automation. By the end of the course, students will be able to formulate nonlinear system models, apply appropriate approximation and stability techniques, and implement control logic for practical applications. Overall, this course builds a solid foundation in nonlinear control, preparing students for advanced research, professional practice, and innovation in electrical, electronic, and control engineering fields. 116",
        "prerequisites": "Nil",
        "clos": [
          {
            "id": "CLO 1",
            "desc": "Describe the fundamental 1,2,4 characteristics of nonlinear systems and common sources of nonlinearities",
            "pos": "PO1, PO2, PO8"
          },
          {
            "id": "CLO 2",
            "desc": "Formulate and analyze nonlinear control systems",
            "pos": "PO1, PO2, PO4"
          },
          {
            "id": "CLO 3",
            "desc": "Apply linearization and 3,4,5 1,2 2,3,6 1,2 approximation methods to simplify and analyze nonlinear systems near equilibrium points",
            "pos": "PO3, PO4, PO5"
          },
          {
            "id": "CLO 4",
            "desc": "Evaluate the behavior of nonlinear 3,4,5 1,2,3,4 control systems through phase- plane analysis, describing function methods, or simulations",
            "pos": "PO1, PO2"
          },
          {
            "id": "CLO 5",
            "desc": "Develop and test control logic for 2,3,6 simple industrial process 3,5,6,11,12 automation using PLCs",
            "pos": "PO2, PO3, PO6"
          },
          {
            "id": "CLO 6",
            "desc": "Describe the fundamental characteristics of nonlinear systems and common sources of nonlinearities",
            "pos": "PO1, PO2"
          },
          {
            "id": "CLO 7",
            "desc": "Formulate and analyze nonlinear control systems",
            "pos": "PO3, PO4, PO5"
          },
          {
            "id": "CLO 8",
            "desc": "Apply linearization and approximation methods to simplify and analyze nonlinear systems near equilibrium points",
            "pos": "PO1, PO2, PO3, PO4"
          },
          {
            "id": "CLO 9",
            "desc": "Evaluate the behavior of nonlinear control systems through phase-plane analysis, describing function methods, or simulations",
            "pos": "PO2, PO3, PO6"
          },
          {
            "id": "CLO 10",
            "desc": "Develop and test control logic for simple industrial process automation using PLCs f)",
            "pos": "PO3, PO5, PO6, PO11, PO12"
          }
        ],
        "outlines": [
          "Week 1-3: Introduction and fundamental concepts.",
          "Week 4-6: Core operations and analytical frameworks.",
          "Week 7-9: Advanced modules and system architectures.",
          "Week 10-12: Practical design case studies and review.",
          "Week 13-15: Revision and comprehensive examinations."
        ],
        "lecturePlans": "Lectures hold on scheduled times per week in Hall B2-5. Mandatory practical and tutorial sessions commence in Week 3, mapping practical observations to theoretical calculations. Mid-semester tests are held in Week 8."
      },
